import math

def prime_fib(n: int):
    """
    Returns the n-th number that is both a Fibonacci number and a prime.
    """
    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2 or num == 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        w = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += w
            w = 6 - w
        return True

    def fibonacci_idx(k: int) -> int:
        a, b = 0, 1
        for _ in range(k):
            a, b = b, a + b
        return a

    count = 0
    fib_idx = 1  # 0 is F0=0 (not prime), start at F1=1
    while True:
        fib_num = fibonacci_idx(fib_idx)
        if is_prime(fib_num):
            count += 1
            if count == n:
                return fib_num
        fib_idx += 1
