import math

def is_multiply_prime(a):
    """
    Return True if the given number a (less than 100) can be expressed as the product of exactly three
    prime numbers (not necessarily distinct), else False.
    """
    if a < 2 or a >= 100:
        return False

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.isqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all primes up to a (though a <= 100, so primes up to 97 are enough)
    primes = [i for i in range(2, a + 1) if is_prime(i)]

    # Enumerate all combinations of three primes whose product equals a
    n_primes = len(primes)
    found = False
    for i in range(n_primes):
        p1 = primes[i]
        if p1 > a:
            break
        for j in range(i, n_primes):
            p2 = primes[j]
            if p1 * p2 > a:
                break
            rem = a // (p1 * p2)
            # Try to find a prime p3 such that p1*p2*p3 == a
            # Since a < 100, rem will be small; check primality
            if rem < 2:
                continue
            if is_prime(rem):
                found = True
                break
            # Also check for cases where one prime is used more than once (e.g., 2*2*5=20)
            # We already covered p1 and p2 varying over all, so duplicates (like p1==p2) are also checked
        if found:
            break
    return found
