def numerical_letter_grade(grades):
    """
    Translates a list of numeric grades (on a 4.0 scale) into letter grades
    using the specified grading table.

    Parameters:
    grades (list of float/int): List of numeric grades (0.0 to 4.0 inclusive)

    Returns:
    list of str: Corresponding list of letter grades
    """
    from typing import List

    def get_letter(gpa):
        if gpa >= 4.0:
            return 'A+'
        elif gpa > 3.7:
            return 'A'
        elif gpa > 3.3:
            return 'A-'
        elif gpa > 3.0:
            return 'B+'
        elif gpa > 2.7:
            return 'B'
        elif gpa > 2.3:
            return 'B-'
        elif gpa > 2.0:
            return 'C+'
        elif gpa > 1.7:
            return 'C'
        elif gpa > 1.3:
            return 'C-'
        elif gpa > 1.0:
            return 'D+'
        elif gpa > 0.7:
            return 'D'
        elif gpa > 0.0:
            return 'D-'
        else:
            return 'E'

    # Use list comprehension for brevity and efficiency
    return [get_letter(g) for g in grades]

