import string

def encrypt(s):
    """
    Rotate the alphabet by 4 positions (since 2 * 2 = 4) and shift each letter accordingly.
    Non-alphabetic characters are left unchanged.
    """
    shift = 4  # Because 2 (given multiplier) * 2 (given rotation) = 4
    result = []
    for ch in s:
        if ch.isalpha():
            # Determine ASCII base depending on the case
            if ch.isupper():
                base = ord('A')
            else:
                base = ord('a')
            # Shift character while wrapping within alphabet
            new_ord = (ord(ch) - base + shift) % 26 + base
            result.append(chr(new_ord))
        else:
            result.append(ch)  # Non-alphabetic characters unchanged
    return ''.join(result)
