import math

def skjkasdkd(lst):
    """
    You are given a list of integers. Find the largest prime number in the list and return the sum of its digits.
    If there is no prime in the list, return 0.
    """

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True  # 2 and 3 are prime
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Find the maximum prime in the list
    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num

    if max_prime is None:
        return 0  # No primes found

    # Sum the digits of the largest prime
    digit_sum = sum(int(d) for d in str(max_prime))
    return digit_sum
