import re

def compare_one(a, b):
    """
    Takes two arguments which can be int, float, or string representations of numbers.
    Returns the larger value in its original type. If they are equal, returns None.
    Strings like "2,3" are interpreted as floats.
    """
    # Helper to convert string number (with comma as decimal) to float
    def to_num(x):
        if isinstance(x, (int, float)):
            return float(x)
        # Try converting string with comma as decimal point
        try:
            # Replace comma with dot for float conversion
            if isinstance(x, str):
                cleaned = x.replace(',', '.')
                return float(cleaned)
            # fallback: try normal float conversion
            return float(x)
        except ValueError:
            raise ValueError(f"Invalid numeric string: {x}")

    # Convert both to float for comparison
    fa = to_num(a)
    fb = to_num(b)

    if fa > fb:
        # Return original type of a if possible
        # Need to reconstruct the original value's type based on a
        # So, if a was a string, use it; else use original
        if isinstance(a, str):
            return a
        else:
            return a  # it's already int or float, so unchanged
    elif fb > fa:
        if isinstance(b, str):
            return b
        else:
            return b
    else:
        return None
